const input = $input.first().json;
const requestId = typeof input.requestId === 'string' && input.requestId ? input.requestId : crypto.randomUUID();
const fail = (message) => [{json:{valid:false,result:{ok:false,requestId,provider:'generic',model:typeof input.model === 'string' ? input.model : '',error:{code:'INVALID_REQUEST',message,retryable:false,httpStatus:null,attempts:0},warnings:[]}}}];
const allowed = new Set(['requestId','provider','model','messages','temperature','maxTokens','output','capabilities','profileBaseUrl','profileTimeoutMs']);
if (Object.keys(input).some((key) => !allowed.has(key))) return fail('Input contains unknown fields');
if (input.provider !== 'generic') return fail('Generic workflow requires provider=generic');
if (typeof input.model !== 'string' || !input.model.trim()) return fail('Model is required');
if (!Array.isArray(input.messages) || input.messages.length < 1 || input.messages.length > 100) return fail('Messages must contain 1..100 items');
if (input.messages.some((m) => !['system','user','assistant'].includes(m?.role) || typeof m?.content !== 'string' || !m.content)) return fail('Message role/content is invalid');
const temperature = input.temperature ?? 0.2; const maxTokens = input.maxTokens ?? 1000;
if (typeof temperature !== 'number' || temperature < 0 || temperature > 1) return fail('Temperature must be 0..1');
if (!Number.isInteger(maxTokens) || maxTokens < 1 || maxTokens > 8192) return fail('maxTokens must be 1..8192');
const mode = input.output?.mode ?? 'text';
if (!['text','json'].includes(mode)) return fail('Output mode must be text or json');
if (input.capabilities?.tools || input.capabilities?.providerStructuredOutput) return [{json:{valid:false,result:{ok:false,requestId,provider:'generic',model:input.model,error:{code:'CAPABILITY_UNSUPPORTED',message:'Requested capability is not enabled for this profile',retryable:false,httpStatus:null,attempts:0},warnings:[]}}}];
return [{json:{valid:true,requestId,provider:'generic',model:input.model,messages:input.messages,temperature,maxTokens,output:{mode,schema:input.output?.schema ?? null},profileBaseUrl:input.profileBaseUrl,profileTimeoutMs:input.profileTimeoutMs}}];

const response=$input.first().json; const request=$('Validate Contract').first().json; const status=Number(response.statusCode ?? 0); const body=response.body ?? response;
const error=(code,message,retryable)=>[{json:{ok:false,requestId:request.requestId,provider:'generic',model:request.model,error:{code,message,retryable,httpStatus:status || null,attempts:1},warnings:[]}}];
if (status===401 || status===403) return error('AUTH_FAILED','Provider authentication failed',false);
if (status===404 || (status===400 && /model/i.test(JSON.stringify(body)))) return error('MODEL_NOT_FOUND','Requested model is unavailable',false);
if (status===429) return error('RATE_LIMITED','Provider rate limit exceeded',true);
if (status>=500 || status===0) return error(status===0?'PROVIDER_UNAVAILABLE':'PROVIDER_UNAVAILABLE','Provider is unavailable',true);
if (status<200 || status>=300) return error('INVALID_PROVIDER_RESPONSE','Provider returned an unsupported response',false);
const content=body?.choices?.[0]?.message?.content; if (typeof content!=='string') return error('INVALID_PROVIDER_RESPONSE','Provider response cannot be normalized',false);
let parsed=null; if (request.output.mode==='json') { try { parsed=JSON.parse(content); } catch { return error('OUTPUT_VALIDATION_FAILED','Provider output is not valid JSON',false); } }
const usage=body.usage ?? {}; return [{json:{ok:true,requestId:request.requestId,provider:'generic',model:body.model ?? request.model,content:request.output.mode==='text'?content:null,json:request.output.mode==='json'?parsed:null,usage:{inputTokens:usage.prompt_tokens ?? null,outputTokens:usage.completion_tokens ?? null,totalTokens:usage.total_tokens ?? null},capabilitiesUsed:[],warnings:[]}}];
